test "metadata raft apply store notifies projection listeners for committed table and range changes" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-topology-listener-store", .{tmp.sub_path});
    defer std.testing.allocator.free(root);

    const Capture = struct {
        table_signals: usize = 0,
        range_signals: usize = 0,
        last_table_id: u64 = 0,
        last_range_group_id: u64 = 0,

        fn onSignal(ptr: *anyopaque, signal: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            switch (signal.kind) {
                .table => {
                    self.table_signals += 1;
                    self.last_table_id = signal.table_id;
                },
                .range => {
                    self.range_signals += 1;
                    self.last_table_id = signal.table_id;
                    self.last_range_group_id = signal.group_id;
                },
                else => {},
            }
        }
    };

    const table_cmd = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_table = .{
            .table_id = 77,
            .name = "docs",
            .schema_json = "{}",
            .indexes_json = "{}",
        },
    });
    defer std.testing.allocator.free(table_cmd);
    const range_cmd = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_range = .{
            .group_id = 1001,
            .table_id = 77,
            .start_key = "",
            .end_key = null,
        },
    });
    defer std.testing.allocator.free(range_cmd);
    const encoded_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = table_cmd },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = range_cmd },
    });
    defer std.testing.allocator.free(encoded_entries);

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();

    var capture = Capture{};
    try store.addProjectionListener(.{
        .ptr = &capture,
        .vtable = &.{
            .on_projection_signal = Capture.onSignal,
        },
    });

    try store.snapshotBuilder().applyBatch(.{
        .group_id = 41,
        .commit_index = 2,
        .entries_bytes = encoded_entries,
    });

    try std.testing.expectEqual(@as(usize, 1), capture.table_signals);
    try std.testing.expectEqual(@as(usize, 1), capture.range_signals);
    try std.testing.expectEqual(@as(u64, 77), capture.last_table_id);
    try std.testing.expectEqual(@as(u64, 1001), capture.last_range_group_id);
}

test "lifecycle listener detach drains callbacks and preserves unrelated listeners" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(
        std.testing.allocator,
        ".zig-cache/tmp/{s}/metadata-lifecycle-listener-detach",
        .{tmp.sub_path},
    );
    defer std.testing.allocator.free(root);

    const Capture = struct {
        entered: std.Io.Event = .unset,
        release: std.Io.Event = .unset,
        projection_calls: std.atomic.Value(usize) = .init(0),
        committed_key_calls: std.atomic.Value(usize) = .init(0),
        block_projection: std.atomic.Value(bool) = .init(false),

        fn onProjection(ptr: *anyopaque, _: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.projection_calls.fetchAdd(1, .acq_rel);
            if (!self.block_projection.load(.acquire)) return;
            self.entered.set(std.Options.debug_io);
            self.release.waitUncancelable(std.Options.debug_io);
        }

        fn matchesCommittedKey(_: *anyopaque, _: CommittedKeySignal) bool {
            return true;
        }

        fn onCommittedKey(ptr: *anyopaque, _: CommittedKeySignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.committed_key_calls.fetchAdd(1, .acq_rel);
        }
    };
    const Dispatch = struct {
        store: *RaftApplyStore,

        fn run(self: *@This()) void {
            const io = self.store.io_impl.io();
            self.store.apply_mutex.lockUncancelable(io);
            defer self.store.apply_mutex.unlock(io);
            for (self.store.projection_listeners.items) |registered| {
                registered.listener.onProjectionSignal(.{
                    .kind = .table,
                    .metadata_group_id = 1,
                });
            }
        }
    };
    const Detach = struct {
        store: *RaftApplyStore,
        registration: LifecycleListenerRegistration,
        started: std.Io.Event = .unset,
        finished: std.atomic.Value(bool) = .init(false),
        removed: bool = false,

        fn run(self: *@This()) void {
            self.started.set(std.Options.debug_io);
            self.removed = self.store.removeLifecycleListeners(self.registration);
            self.finished.store(true, .release);
        }
    };

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();
    var unrelated = Capture{};
    try store.addProjectionListener(.{
        .ptr = &unrelated,
        .vtable = &.{ .on_projection_signal = Capture.onProjection },
    });
    try store.addCommittedKeyListener(.{
        .ptr = &unrelated,
        .vtable = &.{
            .matches_key = Capture.matchesCommittedKey,
            .on_committed_key = Capture.onCommittedKey,
        },
    });

    var owned = Capture{};
    owned.block_projection.store(true, .release);
    const registration = try store.addLifecycleListeners(
        .{ .ptr = &owned, .vtable = &.{ .on_projection_signal = Capture.onProjection } },
        .{ .ptr = &owned, .vtable = &.{
            .matches_key = Capture.matchesCommittedKey,
            .on_committed_key = Capture.onCommittedKey,
        } },
    );

    var dispatch = Dispatch{ .store = &store };
    var dispatch_thread = try std.testing.io.concurrent(Dispatch.run, .{&dispatch});
    defer {
        owned.release.set(std.Options.debug_io);
        dispatch_thread.await(std.testing.io);
    }
    owned.entered.waitUncancelable(std.Options.debug_io);

    var detach = Detach{ .store = &store, .registration = registration };
    var detach_lock_entered: std.Io.Event = .unset;
    var detach_lock_resume: std.Io.Event = .unset;
    var detach_lock_contended: std.atomic.Value(bool) = .init(false);
    test_lifecycle_detach_lock_barrier = .{
        .entered = &detach_lock_entered,
        .resume_event = &detach_lock_resume,
        .contended = &detach_lock_contended,
    };
    defer test_lifecycle_detach_lock_barrier = null;
    var detach_thread = try std.testing.io.concurrent(Detach.run, .{&detach});
    defer {
        detach_lock_resume.set(std.Options.debug_io);
        owned.release.set(std.Options.debug_io);
        detach_thread.await(std.testing.io);
    }
    detach.started.waitUncancelable(std.Options.debug_io);
    detach_lock_entered.waitUncancelable(std.Options.debug_io);
    // The detach call reached the exact apply-lock boundary while the callback
    // owns that lock. Resume it, then release the callback; it cannot return
    // until synchronous dispatch has drained.
    const blocked_at_lock_boundary = !detach.finished.load(.acquire);
    const apply_lock_was_contended = detach_lock_contended.load(.acquire);
    detach_lock_resume.set(std.Options.debug_io);
    owned.release.set(std.Options.debug_io);
    dispatch_thread.await(std.testing.io);
    detach_thread.await(std.testing.io);
    try std.testing.expect(blocked_at_lock_boundary);
    try std.testing.expect(apply_lock_was_contended);
    try std.testing.expect(detach.removed);
    try std.testing.expect(detach.finished.load(.acquire));

    owned.block_projection.store(false, .release);
    store.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = 1 });
    store.notifyCommittedKeyListeners(.{ .metadata_group_id = 1, .key = "table/1" });
    try std.testing.expectEqual(@as(usize, 1), owned.projection_calls.load(.acquire));
    try std.testing.expectEqual(@as(usize, 0), owned.committed_key_calls.load(.acquire));
    try std.testing.expectEqual(@as(usize, 2), unrelated.projection_calls.load(.acquire));
    try std.testing.expectEqual(@as(usize, 1), unrelated.committed_key_calls.load(.acquire));
    test_lifecycle_detach_lock_barrier = null;
    try std.testing.expect(!store.removeLifecycleListeners(registration));
}

test "placement projection commit barrier brackets durability and notification" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(
        std.testing.allocator,
        ".zig-cache/tmp/{s}/metadata-placement-commit-barrier",
        .{tmp.sub_path},
    );
    defer std.testing.allocator.free(root);

    const Capture = struct {
        barrier_active: bool = false,
        began: usize = 0,
        ended: usize = 0,
        placement_signals: usize = 0,
        signal_outside_barrier: bool = false,

        fn begin(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.barrier_active) @panic("nested placement barrier");
            self.barrier_active = true;
            self.began += 1;
        }

        fn end(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (!self.barrier_active) @panic("placement barrier released twice");
            self.barrier_active = false;
            self.ended += 1;
        }

        fn onSignal(ptr: *anyopaque, signal: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (signal.kind != .placement_intent) return;
            self.placement_signals += 1;
            if (!self.barrier_active) self.signal_outside_barrier = true;
        }
    };

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();
    var capture = Capture{};
    try std.testing.expectError(error.InvalidProjectionCommitBarrier, store.addProjectionListener(.{
        .ptr = &capture,
        .commit_barrier_kind = .placement_intent,
        .vtable = &.{ .on_projection_signal = Capture.onSignal },
    }));
    try store.addProjectionListener(.{
        .ptr = &capture,
        .commit_barrier_kind = .placement_intent,
        .vtable = &.{
            .on_projection_signal = Capture.onSignal,
            .before_projection_commit = Capture.begin,
            .after_projection_commit = Capture.end,
        },
    });

    const node = try encodeTransitionCommand(std.testing.allocator, .{ .register_node = .{
        .node_id = 12,
        .role = "data",
        .lifecycle = metadata_table_manager.node_lifecycle_active,
    } });
    defer std.testing.allocator.free(node);
    const registered_store = try encodeTransitionCommand(std.testing.allocator, .{ .register_store = .{
        .store_id = 12,
        .node_id = 12,
        .role = "data",
        .health_class = "healthy",
        .live = true,
    } });
    defer std.testing.allocator.free(registered_store);
    const placement = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_replica_intent = .{
        .expected_metadata_version = null,
        .expected_version_fence = 0,
        .expected_target_drain_requested = false,
        .replacement = .{
            .record = .{ .group_id = 1201, .replica_id = 1, .local_node_id = 12 },
            .store_id = 12,
            .peer_node_ids = &.{12},
        },
    } });
    defer std.testing.allocator.free(placement);
    const entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = node },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = registered_store },
        .{ .term = 1, .index = 3, .entry_type = .normal, .data = placement },
    });
    defer std.testing.allocator.free(entries);

    try store.snapshotBuilder().applyBatch(.{
        .group_id = 41,
        .commit_index = 3,
        .entries_bytes = entries,
    });
    try std.testing.expectEqual(@as(usize, 1), capture.began);
    try std.testing.expectEqual(@as(usize, 1), capture.ended);
    try std.testing.expectEqual(@as(usize, 1), capture.placement_signals);
    try std.testing.expect(!capture.signal_outside_barrier);
    try std.testing.expect(!capture.barrier_active);
}

test "atomic table topology lifecycle notifications stay constant at the initial range limit" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(
        std.testing.allocator,
        ".zig-cache/tmp/{s}/metadata-topology-notification-scale-store",
        .{tmp.sub_path},
    );
    defer std.testing.allocator.free(root);

    const Capture = struct {
        table_signals: usize = 0,
        range_signals: usize = 0,
        committed_keys: usize = 0,

        fn onProjection(ptr: *anyopaque, signal: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            switch (signal.kind) {
                .table => self.table_signals += 1,
                .range => self.range_signals += 1,
                else => {},
            }
        }

        fn matchesCommittedKey(_: *anyopaque, _: CommittedKeySignal) bool {
            return true;
        }

        fn onCommittedKey(ptr: *anyopaque, _: CommittedKeySignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.committed_keys += 1;
        }
    };

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();
    var capture = Capture{};
    _ = try store.addLifecycleListeners(
        .{ .ptr = &capture, .vtable = &.{ .on_projection_signal = Capture.onProjection } },
        .{ .ptr = &capture, .vtable = &.{
            .matches_key = Capture.matchesCommittedKey,
            .on_committed_key = Capture.onCommittedKey,
        } },
    );

    const range_count: usize = topology_protocol.max_initial_ranges;
    const ranges = try std.testing.allocator.alloc(metadata.RangeRecord, range_count);
    defer std.testing.allocator.free(ranges);
    const range_key_storage = try std.testing.allocator.alloc([8]u8, range_count);
    defer std.testing.allocator.free(range_key_storage);
    for (ranges, 0..) |*record, offset| {
        const range_group_id = 10_000 + @as(u64, @intCast(offset));
        record.* = .{
            .group_id = range_group_id,
            .range_id = range_group_id,
            .table_id = 77,
            .start_key = if (offset == 0)
                ""
            else
                try std.fmt.bufPrint(&range_key_storage[offset], "{x:0>4}", .{offset}),
        };
    }
    for (ranges[0 .. ranges.len - 1], ranges[1..]) |*record, next|
        record.end_key = next.start_key;
    const table: metadata.TableRecord = .{
        .table_id = 77,
        .name = "docs",
        .min_ranges = @intCast(range_count),
    };
    const create = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .create = .{
            .expected_transition_generation = 0,
            .table = table,
            .ranges = ranges,
        } },
    });
    defer std.testing.allocator.free(create);
    const create_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = create },
    });
    defer std.testing.allocator.free(create_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = 41,
        .commit_index = 1,
        .entries_bytes = create_entries,
    });

    const fence = try store.getTableTransitionFence(41, table.table_id);
    const drop = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .drop = .{
            .table_id = table.table_id,
            .expected_name = table.name,
            .expected_transition_generation = fence.generation,
            .range_contract = .{ .membership = fence.membership(table.table_id) },
        } },
    });
    defer std.testing.allocator.free(drop);
    const drop_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = drop },
    });
    defer std.testing.allocator.free(drop_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = 41,
        .commit_index = 2,
        .entries_bytes = drop_entries,
    });

    try std.testing.expectEqual(@as(usize, 2), capture.table_signals);
    try std.testing.expectEqual(@as(usize, 0), capture.range_signals);
    try std.testing.expectEqual(@as(usize, 4), capture.committed_keys);
    const remaining_tables = try store.listTables(std.testing.allocator, 41);
    defer store.freeTables(std.testing.allocator, remaining_tables);
    const remaining_ranges = try store.listRanges(std.testing.allocator, 41);
    defer store.freeRanges(std.testing.allocator, remaining_ranges);
    try std.testing.expectEqual(@as(usize, 0), remaining_tables.len);
    try std.testing.expectEqual(@as(usize, 0), remaining_ranges.len);
}

