    try appendInt(alloc, &encoded, u32, 0);
    try appendInt(alloc, &encoded, u64, 1234);
    try encoded.append(alloc, 1);
    try appendInt(alloc, &encoded, u64, 1200);
    try encoded.append(alloc, 0);
    try encoded.append(alloc, 1);
    try encoded.append(alloc, 1);
    try encoded.append(alloc, 0);
    try encoded.append(alloc, 0);
    try encoded.append(alloc, 1);
